# Instrument map for demo.m8s: which CLAP plugin plays each M8 instrument.
#   lextrack m8 examples/demo.m8s --map examples/demo.map
#
# Keys: an instrument number in hex (00-7F), an M8 instrument kind
# (wavsynth, macrosynth, sampler, midiout, fmsynth), or "default".
# A file holding several plugins takes an id after "@".

00 = ~/.clap/Surge XT.clap
fmsynth = ~/.clap/Surge XT.clap
default = ~/.clap/Surge XT.clap
